equest or (http and http.request) or (fluxus and fluxus.request)\n            if type(reqFn) ~= "function" then return nil end\n            local url = string.format("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Asc&limit=100", game.PlaceId)\n            if cursor and cursor ~= "" then url = url .. "&cursor=" .. cursor end\n            local ok, res = pcall(reqFn, { Url = url, Method = "GET" })\n            if not ok or not res then return nil end\n            local body = res.Body or res.body\n            if type(body) ~= "string" or body == "" then return nil end\n            local ok2, data = pcall(function() return Services.HttpService:JSONDecode(body) end)\n            if not ok2 or type(data) ~= "table" then return nil end\n            return data\n        end\n\n        local function findLowServer(maxPlayers)\n            local cursor = ""\n            for _ = 1, 5 do\n                local data = fetchServers(cursor)\n                if not data or not data.data then return nil end\n                for _, srv in ipairs(data.data) do\n                    local playing = tonumber(srv.playing) or 999\n                    local maxP = tonumber(srv.maxPlayers) or 0\n                    if srv.id and srv.id ~= game.JobId and playing < maxP and playing <= maxPlayers then\n                        return srv.id, playing, maxP\n                    end\n                end\n                cursor = data.nextPageCursor\n                if not cursor or cursor == "" then break end\n            end\n            return nil\n        end\n\n\n        Cfg.register(HopSection:CreateTextbox(Cfg.wrap("Textbox", "Max Players", {\n            Name = "Max Players",\n            Placeholder = "4",\n            Default = tostring(NexusState.maxServerPlayers or 4),\n            Callback = function(text)\n                local n = tonumber(text)\n                if n and n >= 1 and n <= 50 then\n                    NexusState.maxServerPlayers = math.floor(n)\n        