374761393,"               return\n            end\n\n            NexusState.exchange.teleported = false\n            NexusState.exchange.oldPosition = nil\n            if NexusState.exchange.method == \"Teleport\" then\n                local npc = Workspace:FindFirstChild(\"NPC\")\n                if npc then\n                    local func = npc:FindFirstChild(\"Function\")\n                    if func then\n                        local nanjiang = func:FindFirstChild(\"Nanjiang\")\n                        if typeof(nanjiang) == \"Instance\" and nanjiang:IsA(\"Model\") then\n                            local hrp = nanjiang:FindFirstChild(\"HumanoidRootPart\")\n                            if hrp then\n                                local char = LocalPlayer.Character\n                                if char then\n                                    local root = char:FindFirstChild(\"HumanoidRootPart\")\n                                    if root then\n                                        NexusState.exchange.oldPosition = root.Position\n                                        root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                        NexusState.exchange.teleported = true\n                                        task.wait(0.3)\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n                if not NexusState.exchange.teleported then\n                    NexusLib:Notify({ Title = \"Exchange\", Message = \"Could not find Nanjiang, teleport failed. Continuing anyway.\", Duration = 3 })\n                end\n            end\n\n            local success, err = pcall(function()\n                Events.Exchange:FireServer(exchangeType, qty)\n            end)\n\n            if NexusState.exchange.teleported and NexusState.exchange.oldPosition then\n                task.wait(0.2)\n                local char = LocalPlayer.Character\n                if char then\n                    local root = char:FindFirstChild(\"HumanoidRootPart\")\n                    if root then\n                        root.CFrame = CFrame.new(NexusState.exchange.oldPosition)\n                        NexusState.exchange.oldPosition = nil\n                        NexusState.exchange.teleported = false\n                    end\n                end\n            end\n\n            if success then\n                NexusLib:Notify({ Title = \"Exchange\", Message = \"Exchanged \" .. qty .. \" \" .. exchangeType .. \"!\", Duration = 2 })\n            else\n                NexusLib:Notify({ Title = \"Exchange\", Message = \"Exchange failed: \" .. tostring(err), Duration = 2 })\n            end\n        end\n    })\nend\n\n-- ============================================================\n-- ===== QUESTS TAB =====\n-- ============================================================\ndo\n    local QuestsTab = Window:CreateTab(\"Quests\")\n    local selectedQuest = \"Easy Quest\"\n\n    -- Open Ticket Quest dialogue without moving the character.\n    -- StartDialogue first: server ignores ChooseDialogueOption with no open dialogue.\n    NexusState.ticketLastFire = NexusState.ticketLastFire or 0\n    NexusState.ticketFailCount = NexusState.ticketFailCount or 0\n    local function ticketGoFire(action)\n        if _G and _G.Events then\n            local sd = _G.Events:FindFirstChild(\"StartDialogue\")\n            local cd = _G.Events:FindFirstChild(\"ChooseDialogueOption\")\n            if not sd or not cd then return false end\n        end\n        local giver = nil\n        pcall(function()\n            local npc = Workspace:FindFirstChild(\"NPC\")\n            local npcFunc = npc and npc:FindFirstChild(\"Function\")\n            giver = npcFunc and npcFunc:FindFirstChild(\"Ticket Quest Giver\")\n        end)\n        if not giver then return false end\n        local extraData = { giver }\n        pcall(function()\n            Events.StartDialogue:FireServer(\"Ticket Quest Giver\", giver)\n        end)\n        task.wait(0.25)\n        local actions = action\n        if type(actions) ~= \"table\" then\n            actions = { actions }\n        end\n        for _, act in ipairs(actions) do\n            pcall(function()\n                Events.ChooseDialogueOption:FireServer(\"Ticket Quest Giver\", 1, act, extraData)\n            end)\n            task.wait(0.2)\n        end\n        task.wait(0.2)\n        return true\n    end\n\n    local function getTicketQuestCooldownRemaining()\n        local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n        local cooldown = userData and userData:FindFirstChild(\"TicketQuestCooldown\")\n        if not cooldown or not (cooldown:IsA(\"NumberValue\") or cooldown:IsA(\"IntValue\")) then\n            return nil\n        end\n        local ok, serverTime = pcall(function()\n            return Workspace:GetServerTimeNow()\n        end)\n        if not ok or type(serverTime) ~= \"number\" then\n            serverTime = tick()\n        end\n        local cooldownValue = tonumber(cooldown.Value)\n        if not cooldownValue then return nil end\n        return math.max(0, cooldownValue - serverTime)\n    end\n\n    local function keepTicketFishingAtCurrentPosition()\n        if not NexusState.autoDoRunning then return false end\n        NexusState.isDoingUseBaitQuest = false\n        enableBasicFishing()\n        Fishing.Flags.AutoFarmBoss = false\n        Fishing.Flags.AutoFarmSecretBoss = false\n        Fishing.Flags.AnchorLock = true\n        return true\n    end\n\n    -- ===== AUTO CLAIM TICKET QUEST =====\n    do\n        local ClaimSection = QuestsTab:CreateSection(\"Auto Claim Ticket Quest\")\n        local questTypes = {\"Easy Quest\", \"Hard Quest\"}\n\n        local function HasActiveQuest()\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not userData then return false end\n            local quest = userData:FindFirstChild(\"Quest\")\n            if not quest then return false end\n            local main = quest:FindFirstChild(\"Main\")\n            if not main then return false end\n            for _, child in pairs(main:GetChildren()) do\n                if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"Folder\") then\n                    local name = child.Name\n                    if name == \"Easy Ticket Quest\" or name == \"Hard Ticket Quest\" then\n                        return true\n                    end\n                end\n            end\n            return false\n        end\n\n        local claimDropdown = Cfg.register(ClaimSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Select Quest Type\", {\n            Name = \"Select Quest Type\",\n            Options = questTypes,\n            Default = selectedQuest,\n            Callback = function(value) selectedQuest = value end\n        })), \"Dropdown\", \"Select Quest Type\", {\n            Name = \"Select Quest Type\",\n            Options = questTypes,\n            Default = selectedQuest,\n            Callback = function(value) selectedQuest = value end\n        })\n\n        local autoClaimToggle = Cfg.register(ClaimSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Claim Ticket Quest (Fast)\", {\n            Name = \"Auto Claim Ticket Quest (Fast)\",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoClaimRunning = value\n                if value then\n                    if NexusState.autoClaimThread then\n                        task.cancel(NexusState.autoClaimThread)\n                        NexusState.autoClaimThread = nil\n                    end\n                    NexusState.autoClaimThread = task.spawn(function()\n                        while NexusState.autoClaimRunning do\n                            pcall(function()\n                                if not HasActiveQuest() then\n                                    local cooldownRemaining = getTicketQuestCooldownRemaining()\n                                    if cooldownRemaining and cooldownRemaining > 0 then return end\n                                    if tick() - (NexusState.ticketLastFire or 0) < 3 then return end\n                                    NexusState.ticketLastFire = tick()\n                                    local selAction = nil\n                                    if selectedQuest == \"Easy Quest\" then\n                                        selAction = \"EasyAcceptQuest\"\n                                    else\n                                        selAction = \"HardAcceptQuest\"\n                                    end\n                                    if ticketGoFire(selAction) and HasActiveQuest() then\n                                        NexusState.ticketFailCount = 0\n                                        NexusLib:Notify({\n                                            Title = \"Quest\",\n                                            Message = \"Claimed \" .. selectedQuest,\n                                            Duration = 2\n                                        })\n                                    else\n                                        NexusState.ticketFailCount = (NexusState.ticketFailCount or 0) + 1\n                                        if NexusState.ticketFailCount == 5 then\n                                            NexusLib:Notify({ Title = \"Quest\", Message = \"Claim failed 5 times. Check NPC or quest type.\", Duration = 4 })\n                                        end\n                                    end\n                                else\n                                    NexusState.ticketFailCount = 0\n                                end\n                            end)\n                            task.wait(0.5)\n                        end\n                    end)\n                else\n                    if NexusState.autoClaimThread then\n                        task.cancel(NexusState.autoClaimThread)\n                        NexusState.autoClaimThread = nil\n                    end\n                    NexusState.ticketFailCount = 0\n                    NexusLib:Notify({ Title = \"Quest\", Message = \"Auto claim stopped\", Duration = 2 })\n                end\n            end\n        })), \"Toggle\", \"Auto Claim Ticket Quest (Fast)\", {\n            Name = \"Auto Claim Ticket Quest (Fast)\",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoClaimRunning = value\n                if value then\n                    if NexusState.autoClaimThread then\n                        task.cancel(NexusState.autoClaimThread)\n                        NexusState.autoClaimThread = nil\n                    end\n                    NexusState.autoClaimThread = task.spawn(function()\n                        while NexusState.autoClaimRunning do\n                            pcall(function()\n                                if not HasActiveQuest() then\n                                    local cooldownRemaining = getTicketQuestCooldownRemaining()\n                                    if cooldownRemaining and cooldownRemaining > 0 then return end\n                                    if tick() - (NexusState.ticketLastFire or 0) < 3 then return end\n                                    NexusState.ticketLastFire = tick()\n                                    local selAction = nil\n                                    if selectedQuest == \"Easy Quest\" then\n                                        selAction = \"EasyAcceptQuest\"\n                                    else\n                                        selAction = \"HardAcceptQuest\"\n                                    end\n                                    if ticketGoFire(selAction) and HasActiveQuest() then\n                                        NexusState.ticketFailCount = 0\n                                        NexusLib:Notify({\n                                            Title = \"Quest\",\n                                            Message = \"Claimed \" .. selectedQuest,\n                                            Duration = 2\n                                        })\n                                    else\n             alUser:Button2Down(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n                            task.wait(0.1)\n                            VirtualUser:Button2Up(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n                            success = true\n                        end\n                    end)\n                end\n\n                if success then\n                    lastInteractTime = now\n                    NexusLib:Notify({ Title = \"Pray\", Message = \"Prayed to \" .. model.Name, Duration = 2 })\n                    break -- only interact with one spirit per pass\n                end\n                end\n                end\n                end\n            end\n        end\n\n        -- Start helper\n        local function startPray()\n            if prayEnabled then return end\n            prayEnabled = true\n            prayThread = task.spawn(function()\n                while prayEnabled do\n                    pcall(scanAndPray)\n                    task.wait(1.5) -- scan every 1.5 seconds\n                end\n            end)\n            NexusLib:Notify({ Title = \"Auto Pray\", Message = \"Enabled\", Duration = 2 })\n        end\n\n        local function stopPray()\n            prayEnabled = false\n            if prayThread then\n                task.cancel(prayThread)\n                prayThread = nil\n            end\n            for _, conn in ipairs(prayConnections) do\n                pcall(function() conn:Disconnect() end)\n            end\n            prayConnections = {}\n            NexusLib:Notify({ Title = \"Auto Pray\", Message = \"Disabled\", Duration = 2 })\n        end\n\n        -- Toggle\n        Cfg.register(PraySection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Teleport + Interact (Pray) Spirit\", {\n            Name = \"Auto Teleport + Interact (Pray) Spirit\",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    startPray()\n                else\n                    stopPray()\n                end\n            end\n        })), \"Toggle\", \"Auto Teleport + Interact (Pray) Spirit\", {\n            Name = \"Auto Teleport + Interact (Pray) Spirit\",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    startPray()\n                else\n                    stopPray()\n                end\n            end\n        })\n    end\n\nend\n\n-- ============================================================\n-- ===== SHOP TAB =====\n-- ============================================================\ndo\n    local ShopTab = Window:CreateTab(\"Shop\")\n\n    -- Index\n    do\n        local IndexSection = ShopTab:CreateSection(\"Index\")\n        IndexSection:CreateButton({\n            Name = \"Unlock all fish\",\n            Callback = function()\n                local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n                if not userData then\n                    NexusLib:Notify({ Title = \"Index\", Message = \"User data not found!\", Duration = 2 })\n                    return\n                end\n                local indexFolder = userData:FindFirstChild(\"Index\")\n                if not indexFolder then\n                    NexusLib:Notify({ Title = \"Index\", Message = \"Index folder not found!\", Duration = 2 })\n                    return\n                end\n                local count = 0\n                for _, child in ipairs(indexFolder:GetChildren()) do\n                    if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"NumberValue\") or child:IsA(\"IntValue\") then\n                        child.Value = 1\n                        count = count + 1\n                    elseif typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"BoolValue\") then\n                        child.Value = true\n                        count = count + 1\n                    end\n                end\n            end\n        })\n    end\n\n    -- Upgrade Skill\n    do\n        local UpgradeSkillSection = ShopTab:CreateSection(\"Upgrade Skill\")\n        local function GetOwnedSkills()\n            local userId = LocalPlayer and LocalPlayer.UserId\n            if not userId then return {} end\n            local userData = Data and Data:FindFirstChild(tostring(userId))\n            if not userData then return {} end\n            local skillFolder = userData:FindFirstChild(\"Skill\")\n            if not skillFolder then return {} end\n            local ownedSkills = {}\n            for _, child in pairs(skillFolder:GetChildren()) do\n                if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"Folder\") then\n                    local owned = child:FindFirstChild(\"Owned\")\n                    if typeof(owned) == \"Instance\" and owned:IsA(\"BoolValue\") and owned.Value == true then\n                        table.insert(ownedSkills, child.Name)\n                    end\n                end\n            end\n            return ownedSkills\n        end\n\n        local skillOptions = GetOwnedSkills()\n        if #skillOptions == 0 then skillOptions = {\"No skill owned\"} end\n        local selectedSkill = skillOptions[1] or \"No skill owned\"\n\n        local skillDropdown = Cfg.register(UpgradeSkillSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Choose A Skill That Needs To Upgrade\", {\n            Name = \"Choose A Skill That Needs To Upgrade\",\n            Options = skillOptions,\n            Default = selectedSkill,\n            Callback = function(value) selectedSkill = value end\n        })), \"Dropdown\", \"Choose A Skill That Needs To Upgrade\", {\n            Name = \"Choose A Skill That Needs To Upgrade\",\n            Options = skillOptions,\n            Default = selectedSkill,\n            Callback = function(value) selectedSkill = value end\n        })\n\n        local upgradeSkillMethodDropdown = Cfg.register(UpgradeSkillSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Upgrade Method\", {\n            Name = \"Upgrade Method\",\n            Options = {\"Instant\", \"Teleport\"},\n            Default = NexusState.upgradeSkill.method or \"Instant\",\n            Callback = function(value) NexusState.upgradeSkill.method = value end\n        })), \"Dropdown\", \"Upgrade Method\", {\n            Name = \"Upgrade Method\",\n            Options = {\"Instant\", \"Teleport\"},\n            Default = NexusState.upgradeSkill.method or \"Instant\",\n            Callback = function(value) NexusState.upgradeSkill.method = value end\n        })\n\n        UpgradeSkillSection:CreateButton({\n            Name = \"Upgrade Selected Skill\",\n            Callback = function()\n                if selectedSkill == \"No skill owned\" or not selectedSkill then\n                    NexusLib:Notify({ Title = \"Upgrade Skill\", Message = \"No skill selected!\", Duration = 2 })\n                    return\n                end\n                local userId = LocalPlayer and LocalPlayer.UserId\n                if not userId then\n                    NexusLib:Notify({ Title = \"Upgrade Skill\", Message = \"Player not ready!\", Duration = 2 })\n                    return\n                end\n                local userData = Data and Data:FindFirstChild(tostring(userId))\n                if not userData then\n                    NexusLib:Notify({ Title = \"Upgrade Skill\", Message = \"User data not found!\", Duration = 2 })\n                    return\n                end\n                local essenceOrb = userData:FindFirstChild(\"EssenceOrb\")\n                if not essenceOrb or not (typeof(essenceOrb) == \"Instance\" and essenceOrb:IsA(\"NumberValue\")) then\n                    NexusLib:Notify({ Title = \"Upgrade Skill\", Message = \"EssenceOrb not found!\", Duration = 2 })\n                    return\n                end\n                if essenceOrb.Value <= 0 then\n                    NexusLib:Notify({ Title = \"Upgrade Skill\", Message = \"Not enough EssenceOrb!\", Duration = 2 })\n                    return\n                end\n                if not Events or not Events.UpgradeSkill then\n                    NexusLib:Notify({ Title = \"Upgrade Skill\", Message = \"UpgradeSkill remote not found!\", Duration = 2 })\n                    return\n                end\n\n                NexusState.upgradeSkill.teleported = false\n                NexusState.upgradeSkill.oldPosition = nil\n                if NexusState.upgradeSkill.method == \"Teleport\" then\n                    local npc = Workspace:FindFirstChild(\"NPC\")\n                    if npc then\n                        local func = npc:FindFirstChild(\"Function\")\n                        if func then\n                            local zengTianguo = func:FindFirstChild(\"Zeng Tianguo\")\n                            if typeof(zengTianguo) == \"Instance\" and zengTianguo:IsA(\"Model\") then\n                                local hrp = zengTianguo:FindFirstChild(\"HumanoidRootPart\")\n                                if hrp then\n                                    local char = LocalPlayer.Character\n                                    if char then\n                                        local root = char:FindFirstChild(\"HumanoidRootPart\")\n                                        if root then\n                                            NexusState.upgradeSkill.oldPosition = root.Position\n                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                            NexusState.upgradeSkill.teleported = true\n                                            task.wait(0.3)\n                                        end\n                                    end\n                                end\n                            end\n                        end\n                    end\n                    if not NexusState.upgradeSkill.teleported then\n                        NexusLib:Notify({ Title = \"Upgrade Skill\", Message = \"Could not find Zeng Tianguo, teleport failed. Continuing anyway.\", Duration = 3 })\n                    end\n                end\n\n                local success, err = pcall(function()\n                    return Events.UpgradeSkill:InvokeServer(selectedSkill)\n                end)\n\n                if NexusState.upgradeSkill.teleported and NexusState.upgradeSkill.oldPosition then\n                    task.wait(0.2)\n                    local char = LocalPlayer.Character\n                    if char then\n                        local root = char:FindFirstChild(\"HumanoidRootPart\")\n                        if root then\n                            root.CFrame = CFrame.new(NexusState.upgradeSkill.oldPosition)\n                            NexusState.upgradeSkill.oldPosition = nil\n                            NexusState.upgradeSkill.teleported = false\n                        end\n                    end\n                end\n\n                if success then\n                    NexusLib:Notify({ Title = \"Upgrade Skill\", Message = \"Upgraded \" .. selectedSkill .. \"!\", Duration = 2 })\n                else\n                    NexusLib:Notify({ Title = \"Upgrade Skill\", Message = \"Failed: \" .. tostring(err), Duration = 2 })\n                end\n            end\n        })\n    end\n\n    -- Craft Rod\n    do\n        local CraftRodSection = ShopTab:CreateSection(\"Craft Rod\")\n        local ROD_RECIPES = {\n            [\"Heavenpiercer Rod\"] = {\n                {name = \"Flying Fish Emperor\", minKg = 1000000, maxKg = 3000000},\n                {name = \"Flying Fish Empress\", minKg = 1000000, maxKg = 3000000},\n                {name = \"Heavenpiercer Turtle\", minKg = 3000000, maxKg = 6000000},\n                {name = \"Rainbow Dragonfish\", minKg = 5000000, maxKg = 8000000},\n            },\n            [\"Pure Diamond Rod\"] = {\n                {name = \"Frost Kingfish\", minKg = 4000000, maxKg = 7000000},\n                {name = \"Frost Queenfish\", minKg = 4000000, maxKg = 8000000},\n                {name = \"Sanguine Fish\", minKg = 3000000, maxKg = 6000000},\n                {name = \"Draconic Koi\", minKg = 1000000, maxKg = 3000000},\n            },\n            [\"Sacred Bamboo Rod\"] = {\n                {name = \"Nameless Octoparasite\", minKg = 6000000, maxKg = 9000000},\n    ning = true\n                NexusLib:Notify({ Title = \"Reroll\", Message = \"Reroll started... Target: \" .. targetTrait, Duration = 2 })\n\n                NexusState.Reroll.thread = task.spawn(function()\n                    local successCount = 0\n                    while NexusState.Reroll.running do\n                        local p2 = Data and Data:FindFirstChild(tostring(LocalPlayer.UserId))\n                        local count = p2 and p2:FindFirstChild(\"Trait Reroll\")\n                        if count and count.Value <= 0 then\n                            NexusLib:Notify({ Title = \"Reroll\", Message = \"No rerolls left, stopping\", Duration = 2 })\n                            break\n                        end\n                        local success, result = pcall(function()\n                            return RerollTrait:InvokeServer(skillName, ignoreLocked)\n                        end)\n                        if not success or not result then\n                            NexusLib:Notify({ Title = \"Reroll\", Message = \"Reroll failed, stopping\", Duration = 2 })\n                            break\n                        end\n                        successCount = successCount + 1\n                        local traitName = result.Name\n                        if traitName == targetTrait then\n                            NexusLib:Notify({ Title = \"Reroll\", Message = \"Got \" .. targetTrait .. \" on \" .. skillName .. \" after \" .. successCount .. \" rerolls!\", Duration = 3 })\n                            break\n                        end\n                        task.wait(0.15)\n                    end\n\n                    if NexusState.Reroll.teleported and NexusState.Reroll.oldPosition then\n                        local char = LocalPlayer.Character\n                        if char then\n                            local root = char:FindFirstChild(\"HumanoidRootPart\")\n                            if root then\n                                root.CFrame = CFrame.new(NexusState.Reroll.oldPosition)\n                                NexusState.Reroll.oldPosition = nil\n                                NexusState.Reroll.teleported = false\n                            end\n                        end\n                    end\n                    NexusState.Reroll.running = false\n                    NexusState.Reroll.thread = nil\n                    NexusLib:Notify({ Title = \"Reroll\", Message = \"Stopped\", Duration = 2 })\n                end)\n            end\n        })\n    end\n\n    -- Craft Bait\n    do\n        local CraftSection = ShopTab:CreateSection(\"Craft Bait\")\n        Cfg.register(CraftSection:CreateTextbox(Cfg.wrap(\"Textbox\", \"Number of baits to craft\", {\n            Name = \"Number of baits to craft\",\n            Placeholder = \"1\",\n            Default = \"1\",\n            Callback = function(value)\n                local num = tonumber(value)\n                if num and num >= 1 then\n                    NexusState.craftBaitQuantity = math.floor(num)\n                else\n                    NexusState.craftBaitQuantity = 1\n                end\n            end\n        })), \"Textbox\", \"Number of baits to craft\", {\n            Name = \"Number of baits to craft\",\n            Placeholder = \"1\",\n            Default = \"1\",\n            Callback = function(value)\n                local num = tonumber(value)\n                if num and num >= 1 then\n                    NexusState.craftBaitQuantity = math.floor(num)\n                else\n                    NexusState.craftBaitQuantity = 1\n                end\n            end\n        })\n\n        Cfg.register(CraftSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Choose a Bait\", {\n            Name = \"Choose a Bait\",\n            Options = {\"Rainbow Bait\", \"Frost Bait\", \"Nameless Bait\"},\n            Default = \"Rainbow Bait\",\n            Callback = function(value) NexusState.craftBaitName = value end\n        })), \"Dropdown\", \"Choose a Bait\", {\n            Name = \"Choose a Bait\",\n            Options = {\"Rainbow Bait\", \"Frost Bait\", \"Nameless Bait\"},\n            Default = \"Rainbow Bait\",\n            Callback = function(value) NexusState.craftBaitName = value end\n        })\n\n        Cfg.register(CraftSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Craft Method\", {\n            Name = \"Craft Method\",\n            Options = {\"Instant\", \"Teleport\"},\n            Default = \"Instant\",\n            Callback = function(value) NexusState.craftBaitMethod = value end\n        })), \"Dropdown\", \"Craft Method\", {\n            Name = \"Craft Method\",\n            Options = {\"Instant\", \"Teleport\"},\n            Default = \"Instant\",\n            Callback = function(value) NexusState.craftBaitMethod = value end\n        })\n\n        local BAIT_RECIPES = {\n            [\"Rainbow Bait\"] = {\n                {name = \"Colossal Tigerfish\", minKg = 3000000, maxKg = 6000000},\n                {name = \"Heavenpiercer Turtle\", minKg = 3000000, maxKg = 6000000},\n                {name = \"Golden Guardian Fish\", minKg = 1000000, maxKg = 3000000},\n                {name = \"Crimson Electric Eel\", minKg = 3000000, maxKg = 4000000},\n            },\n            [\"Frost Bait\"] = {\n                {name = \"Frost Kingfish\", minKg = 4000000, maxKg = 7000000},\n                {name = \"Ascended Perch\", minKg = 900000, maxKg = 1000000},\n                {name = \"Primordial Kunfish Overlord\", minKg = 1000000, maxKg = 1600000},\n                {name = \"Warbringer Shark\", minKg = 500000, maxKg = 800000},\n            },\n            [\"Nameless Bait\"] = {\n                {name = \"Mountain Fish\", minKg = 1000000, maxKg = 5000000},\n                {name = \"Tiger Mirefish\", minKg = 1000000, maxKg = 3000000},\n                {name = \"Mirage Lanternfish\", minKg = 3000000, maxKg = 5000000},\n                {name = \"Octoparasitic Fish\", minKg = 3000000, maxKg = 5000000},\n            }\n        }\n\n        local function checkMaterials(baitName, quantity)\n            local recipe = BAIT_RECIPES[baitName]\n            if not recipe then return false, \"No recipe found for \" .. baitName end\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not userData then return false, \"Player data not found\" end\n            local inventory = userData:FindFirstChild(\"Inventory\")\n            if not inventory then return false, \"Inventory not found\" end\n            local fishCount = {}\n            for _, req in ipairs(recipe) do fishCount[req.name] = 0 end\n            for _, item in pairs(inventory:GetChildren()) do\n                local fishName, weight, count = parseCraftFishEntry(item)\n                if fishName and fishName ~= \"\" then\n                    local req = nil\n                    for _, r in ipairs(recipe) do\n                        if r.name == fishName then req = r; break end\n                    end\n                    if req then\n                        if weight and weight >= req.minKg and weight <= req.maxKg then\n                            fishCount[req.name] = fishCount[req.name] + count\n                        end\n                    end\n                end\n            end\n            local missing = {}\n            for _, req in ipairs(recipe) do\n                local count = fishCount[req.name] or 0\n                if count < quantity then\n                    table.insert(missing, req.name .. \" (can \" .. quantity .. \", co \" .. count .. \")\")\n                end\n            end\n            if #missing > 0 then\n                return false, \"Missing materials: \" .. table.concat(missing, \", \")\n            end\n            return true, \"Materials are sufficient!\"\n        end\n\n        local function craftBait()\n            local qty = NexusState.craftBaitQuantity\n            local ok, msg = checkMaterials(NexusState.craftBaitName, qty)\n            if not ok then\n                NexusLib:Notify({ Title = \"Craft Bait\", Message = msg, Duration = 4 })\n                return\n            end\n            local method = NexusState.craftBaitMethod or \"Instant\"\n            local teleported = false\n            if method == \"Teleport\" then\n                local npc = Workspace:FindFirstChild(\"NPC\")\n                if npc then\n                    local buyBait = npc:FindFirstChild(\"BuyBait\")\n                    if buyBait then\n                        local children = buyBait:GetChildren()\n                        if #children >= 5 then\n                            local targetModel = children[5]\n                            if typeof(targetModel) == \"Instance\" and targetModel:IsA(\"Model\") then\n                                local hrp = targetModel:FindFirstChild(\"HumanoidRootPart\")\n                                if hrp then\n                                    local char = LocalPlayer.Character\n                                    if char then\n                                        local root = char:FindFirstChild(\"HumanoidRootPart\")\n                                        if root then\n                                            NexusState.lastCraftBaitPosition = root.Position\n                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                            teleported = true\n                                            task.wait(0.3)\n                                        end\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n            end\n            local success, err = pcall(function()\n                Events.CraftBait:FireServer(NexusState.craftBaitName, qty)\n            end)\n            if success then\n                NexusLib:Notify({ Title = \"Craft Bait\", Message = \"Crafted \" .. qty .. \"x \" .. NexusState.craftBaitName, Duration = 2 })\n            else\n                NexusLib:Notify({ Title = \"Craft Bait\", Message = \"Failed: \" .. tostring(err), Duration = 2 })\n            end\n            if teleported and NexusState.lastCraftBaitPosition then\n                task.wait(0.3)\n                local char = LocalPlayer.Character\n                if char then\n                    local root = char:FindFirstChild(\"HumanoidRootPart\")\n                    if root then\n                        root.CFrame = CFrame.new(NexusState.lastCraftBaitPosition)\n                        NexusState.lastCraftBaitPosition = nil\n                    end\n                end\n            end\n        end\n\n        local autoCraftToggle = Cfg.register(CraftSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto craft bait\", {\n            Name = \"Auto craft bait\",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoCraftRunning = value\n                if value then\n                    if NexusState.autoCraftThread then\n                        task.cancel(NexusState.autoCraftThread)\n                        NexusState.autoCraftThread = nil\n                    end\n                    NexusState.autoCraftThread = task.spawn(function()\n                        while NexusState.autoCraftRunning do\n                            pcall(craftBait)\n                            task.wait(5)\n                        end\n                    end)\n                else\n                    if NexusState.autoCraftThread then\n                        task.cancel(NexusState.autoCraftThread)\n                        NexusState.autoCraftThread = nil\n                    end\n                end\n            end\n        })), \"Toggle\", \"Auto craft bait\", {\n            Name = \"Auto craft bait\",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoCraftRunning = value\n                if value then\n                    if NexusState.autoCraftThread then\n                        task.cancel(NexusState.autoCraftThread)\n                        NexusState.autoCraftThread = nil\n                    end\n                    NexusState.autoCraftThread = task.spawn(function()\n                        while NexusState.autoCraftRunning do\n                          startGodEsp()\n                    else\n                        stopGodEsp()\n                    end\n                end\n            })), \"Toggle\", \"God ESP\", {\n                Name = \"God ESP\",\n                Default = false,\n                Callback = function(value)\n                    if value then\n                        startGodEsp()\n                    else\n                        stopGodEsp()\n                    end\n                end\n            })\n        end\n        \n        -- ===== NPCs ESP =====\n        do\n            local npcEspEnabled = false\n            local npcEspThread = nil\n            local npcEspHighlights = {}\n            local npcFolder = workspace:FindFirstChild(\"NPC\") and workspace.NPC:FindFirstChild(\"Function\")\n            \n            local function createNpcEsp(npcModel)\n                if not npcModel or typeof(npcModel) ~= \"Instance\" or not npcModel:IsA(\"Model\") then return end\n                if npcEspHighlights[npcModel] then return end\n                \n                if not npcModel.Parent or typeof(npcModel.Parent) ~= \"Instance\" or not npcModel.Parent:IsA(\"Folder\") then return end\n                \n                local attachPart = npcModel:FindFirstChildWhichIsA(\"BasePart\")\n                if not attachPart then\n                    attachPart = npcModel:FindFirstChildWhichIsA(\"BasePart\", true)\n                end\n                if not attachPart then return end\n                \n                local highlight = Instance.new(\"Highlight\")\n                highlight.FillColor = Color3.fromRGB(255, 100, 0)\n                highlight.FillTransparency = 0.4\n                highlight.OutlineColor = Color3.fromRGB(255, 200, 50)\n                highlight.OutlineTransparency = 0.2\n                highlight.Adornee = npcModel\n                highlight.Parent = npcModel\n                \n                local billboard = Instance.new(\"BillboardGui\")\n                billboard.Name = \"NpcEspBillboard\"\n                billboard.Size = UDim2.new(0, 200, 0, 30)\n                billboard.StudsOffset = Vector3.new(0, 2.5, 0)\n                billboard.AlwaysOnTop = true\n                billboard.Parent = attachPart\n                \n                local frame = Instance.new(\"Frame\")\n                frame.Size = UDim2.new(1, 0, 1, 0)\n                frame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)\n                frame.BackgroundTransparency = 0.5\n                frame.BorderSizePixel = 0\n                frame.Parent = billboard\n                \n                local corner = Instance.new(\"UICorner\")\n                corner.CornerRadius = UDim.new(0, 4)\n                corner.Parent = frame\n                \n                local label = Instance.new(\"TextLabel\")\n                label.Size = UDim2.new(1, 0, 1, 0)\n                label.BackgroundTransparency = 1\n                label.Font = Enum.Font.GothamBold\n                label.TextSize = 14\n                label.TextColor3 = Color3.fromRGB(255, 150, 50)\n                label.Text = \"NPC | \" .. npcModel.Name\n                label.TextScaled = false\n                label.TextXAlignment = Enum.TextXAlignment.Center\n                label.TextYAlignment = Enum.TextYAlignment.Center\n                label.Parent = frame\n                \n                npcEspHighlights[npcModel] = {\n                    highlight = highlight,\n                    billboard = billboard,\n                    attachPart = attachPart,\n                }\n            end\n            \n            local function removeNpcEsp(npcModel)\n                local data = npcEspHighlights[npcModel]\n                if data then\n                    if data.highlight then data.highlight:Destroy() end\n                    if data.billboard then data.billboard:Destroy() end\n                    npcEspHighlights[npcModel] = nil\n                end\n            end\n            \n            local function clearAllNpcEsp()\n                for model, data in pairs(npcEspHighlights) do\n                    pcall(function()\n                        if data.highlight then data.highlight:Destroy() end\n                        if data.billboard then data.billboard:Destroy() end\n                    end)\n                end\n                npcEspHighlights = {}\n            end\n            \n            local function scanAllNpcs()\n                if not npcFolder then return end\n                for _, child in ipairs(npcFolder:GetDescendants()) do\n                    if typeof(child) == \"Instance\" and child:IsA(\"Model\") and child.Parent and typeof(child.Parent) == \"Instance\" and child.Parent:IsA(\"Folder\") then\n                        if not npcEspHighlights[child] then\n                            pcall(function() createNpcEsp(child) end)\n                        end\n                    end\n                end\n            end\n            \n            local function startNpcEsp()\n                if npcEspEnabled then return end\n                npcEspEnabled = true\n                scanAllNpcs()\n                \n                if npcFolder then\n                    local npcAddedConn = npcFolder.DescendantAdded:Connect(function(desc)\n                        if npcEspEnabled and typeof(desc) == \"Instance\" and desc:IsA(\"Model\") and desc.Parent and typeof(desc.Parent) == \"Instance\" and desc.Parent:IsA(\"Folder\") then\n                            task.wait(0.1)\n                            pcall(function()\n                                if not npcEspHighlights[desc] then\n                                    createNpcEsp(desc)\n                                end\n                            end)\n                        end\n                    end)\n                    table.insert(espConnections, { conn = npcAddedConn })\n                end\n                \n                npcEspThread = task.spawn(function()\n                    while npcEspEnabled do\n                        task.wait(10)\n                        if npcEspEnabled then\n                            pcall(function()\n                                for model, data in pairs(npcEspHighlights) do\n                                    if not model.Parent then\n                                        removeNpcEsp(model)\n                                    end\n                                end\n                                scanAllNpcs()\n                            end)\n                        end\n                    end\n                end)\n                \n                NexusLib:Notify({ Title = \"NPCs ESP\", Message = \"NPCs ESP enabled!\", Duration = 2 })\n            end\n            \n            local function stopNpcEsp()\n                npcEspEnabled = false\n                if npcEspThread then\n                    task.cancel(npcEspThread)\n                    npcEspThread = nil\n                end\n                clearAllNpcEsp()\n                NexusLib:Notify({ Title = \"NPCs ESP\", Message = \"NPCs ESP disabled!\", Duration = 2 })\n            end\n            \n            Cfg.register(EspSection:CreateToggle(Cfg.wrap(\"Toggle\", \"NPCs ESP\", {\n                Name = \"NPCs ESP\",\n                Default = false,\n                Callback = function(value)\n                    if value then\n                        startNpcEsp()\n                    else\n                        stopNpcEsp()\n                    end\n                end\n            })), \"Toggle\", \"NPCs ESP\", {\n                Name = \"NPCs ESP\",\n                Default = false,\n                Callback = function(value)\n                    if value then\n                        startNpcEsp()\n                    else\n                        stopNpcEsp()\n                    end\n                end\n            })\n        end\n    end\nend\n\n-- ============================================================\n-- ===== DEFINE _G.codetorun AND _G.codes =====\n-- ============================================================\n\n_G.codetorun = [[\n    -- Use the globals assigned by the main script\n    local RunService = _G.RunService\n    local LocalPlayer = _G.LocalPlayer\n    local UserInputService = _G.UserInputService\n    local VirtualUser = _G.VirtualUser\n    local Events = _G.Events\n    local MiscFlags = _G.MiscFlags\n    local alive = _G.alive\n    local runtimeEnv = _G.runtimeEnv\n\n    local noclipAccum = 0\n    if runtimeEnv.NexusNoclipConn then pcall(function() runtimeEnv.NexusNoclipConn:Disconnect() end) end\n    runtimeEnv.NexusNoclipConn = RunService.Stepped:Connect(function(_, dt)\n        if not alive() then return end\n        if not MiscFlags.Noclip then return end\n        noclipAccum = noclipAccum + (dt or 0.016)\n        if noclipAccum < 0.4 then return end\n        noclipAccum = 0\n        local char = LocalPlayer.Character\n        if char then\n            for _, v in ipairs(char:GetDescendants()) do\n                if typeof(v) == \"Instance\" and v:IsA(\"BasePart\") and v.CanCollide then v.CanCollide = false end\n            end\n        end\n    end)\n\n    UserInputService.JumpRequest:Connect(function()\n        if MiscFlags.InfiniteJump and LocalPlayer.Character then\n            local h = LocalPlayer.Character:FindFirstChildOfClass('Humanoid')\n            if h then h:ChangeState(Enum.HumanoidStateType.Jumping) end\n        end\n    end)\n\n    local function nudgeInput()\n        if _G.Fishing and _G.Fishing.Flags and not _G.Fishing.Flags.AntiAFK then return end\n        local _nm = false\n        pcall(function()\n            local _c = LocalPlayer.Character\n            local _h = _c and _c:FindFirstChildOfClass(\"Humanoid\")\n            local _md = _h and _h.MoveDirection\n            if _md and (math.abs(_md.X or 0) + math.abs(_md.Z or 0) > 0.05) then _nm = true end\n        end)\n        if _nm then return end\n        pcall(function()\n            if Events and Events:FindFirstChild(\"AFK\") then\n                Events.AFK:FireServer()\n            end\n            if VirtualUser then\n                VirtualUser:Button2Down(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n                task.wait(0.2)\n                VirtualUser:Button2Up(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n            end\n        end)\n    end\n\n    if runtimeEnv.AntiAFKConnection then pcall(function() runtimeEnv.AntiAFKConnection:Disconnect() end) end\n    runtimeEnv.AntiAFKConnection = LocalPlayer.Idled:Connect(function()\n        if _G.Fishing and _G.Fishing.Flags and not _G.Fishing.Flags.AntiAFK then return end