36078.,"NexusPremiumVerified","r.Character\n                if not character then\n                    NexusLib:Notify({ Title = \"Teleport\", Message = targetPlayer.Name .. \" has no character!\", Duration = 2 })\n                    return\n                end\n                \n                local hrp = character:FindFirstChild(\"HumanoidRootPart\")\n                if not hrp then\n                    NexusLib:Notify({ Title = \"Teleport\", Message = \"Cannot find HumanoidRootPart!\", Duration = 2 })\n                    return\n                end\n                \n                local myChar = LocalPlayer.Character\n                if not myChar then return end\n                local myHrp = myChar:FindFirstChild(\"HumanoidRootPart\")\n                if not myHrp then return end\n                \n                myHrp.CFrame = hrp.CFrame + Vector3.new(0, 3, 0)\n                \n                NexusLib:Notify({\n                    Title = \"Teleport\",\n                    Message = \"Teleported to \" .. targetPlayer.Name,\n                    Duration = 2\n                })\n            end\n        })\n    -- ===== SPECTATE PLAYER =====\n        local spectateEnabled = false\n        local spectateTarget = nil\n        local oldSubject = nil\n        local oldCameraType = nil\n        local espConnections = {}\n        \n        -- Start spectate\n        local function startSpectate()\n            if spectateEnabled then return end\n            \n            -- Find the first player other than yourself\n            local targetPlayer = nil\n            for _, player in ipairs(Players:GetPlayers()) do\n                if player ~= LocalPlayer then\n                    targetPlayer = player\n                    break\n                end\n            end\n            \n            if not targetPlayer then\n                NexusLib:Notify({ Title = \"Spectate\", Message = \"No other players to spectate!\", Duration = 2 })\n                if NexusState.spectateToggle then\n                    NexusState.spectateToggle:Set(false)\n                end\n                return\n            end\n            \n            -- Check whether the target has a character\n            if not targetPlayer.Character then\n                NexusLib:Notify({ Title = \"Spectate\", Message = targetPlayer.Name .. \" has no character!\", Duration = 2 })\n                if NexusState.spectateToggle then\n                    NexusState.spectateToggle:Set(false)\n                end\n                return\n            end\n            \n            local targetHrp = targetPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n            if not targetHrp then\n                NexusLib:Notify({ Title = \"Spectate\", Message = \"Cannot find HumanoidRootPart of \" .. targetPlayer.Name, Duration = 2 })\n                if NexusState.spectateToggle then\n                    NexusState.spectateToggle:Set(false)\n                end\n                return\n            end\n            \n            spectateEnabled = true\n            spectateTarget = targetPlayer\n            \n            local camera = workspace.CurrentCamera\n            oldSubject = camera.CameraSubject\n            oldCameraType = camera.CameraType\n            \n            -- Lock the camera onto the target\n            camera.CameraSubject = targetHrp\n            camera.CameraType = Enum.CameraType.Custom\n            \n            NexusLib:Notify({ Title = \"Spectate\", Message = \"Spectating \" .. targetPlayer.Name, Duration = 2 })\n        end\n        \n        -- Stop spectate\n        local function stopSpectate()\n            spectateEnabled = false\n            spectateTarget = nil\n            \n            -- Reset the camera back to the local player\n            pcall(function()\n                local camera = workspace.CurrentCamera\n                if oldSubject then\n                    camera.CameraSubject = oldSubject\n                    oldSubject = nil\n                end\n                if oldCameraType then\n                    camera.CameraType = oldCameraType\n                    oldCameraType = nil\n                end\n            end)\n            \n            NexusLib:Notify({ Title = \"Spectate\", Message = \"Stopped spectating\", Duration = 2 })\n        end\n        \n        -- Toggle Spectate Player\n        local spectateToggle = Cfg.register(PlayerSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Spectate Player\", {\n            Name = \"Spectate Player\",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    startSpectate()\n                else\n                    stopSpectate()\n                end\n            end\n        })), \"Toggle\", \"Spectate Player\", {\n            Name = \"Spectate Player\",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    startSpectate()\n                else\n                    stopSpectate()\n                end\n            end\n        })\n        \n        -- Persist the toggle in NexusState\n        NexusState.spectateToggle = spectateToggle\n        \n        -- Handle the target leaving or their character resetting\n        local function onTargetCharacterAdded()\n            if spectateEnabled and spectateTarget then\n                local char = spectateTarget.Character\n                if char then\n                    local hrp = char:FindFirstChild(\"HumanoidRootPart\")\n                    if hrp then\n                        workspace.CurrentCamera.CameraSubject = hrp\n                    end\n                end\n            end\n        end\n        \n        -- Listen for the target's character changing\n        local charAddedConn = nil\n        local playerRemovingConn = Players.PlayerRemoving:Connect(function(player)\n            if spectateEnabled and player == spectateTarget then\n                stopSpectate()\n                if NexusState.spectateToggle then\n                    NexusState.spectateToggle:Set(false)\n                end\n            end\n        end)\n        \n        -- While spectating, watch the target's CharacterAdded\n        local function monitorTarget()\n            if spectateEnabled and spectateTarget then\n                if charAddedConn then charAddedConn:Disconnect() end\n                charAddedConn = spectateTarget.CharacterAdded:Connect(function()\n                    task.wait(0.5)\n                    onTargetCharacterAdded()\n                end)\n            else\n                if charAddedConn then\n                    charAddedConn:Disconnect()\n                    charAddedConn = nil\n                end\n            end\n        end\n        \n        -- Wrap startSpectate to attach the monitor\n        local originalStart = startSpectate\n        startSpectate = function()\n            originalStart()\n            monitorTarget()\n        end\n        \n        -- Wrap stopSpectate to clean up\n        local originalStop = stopSpectate\n        stopSpectate = function()\n            originalStop()\n            if charAddedConn then\n                charAddedConn:Disconnect()\n                charAddedConn = nil\n            end\n        end\n        \n        table.insert(espConnections, { conn = playerRemovingConn })\n    end\n    -- ===== NPCs SECTION =====\n    do\n        local NpcSection = TeleportTab:CreateSection(\"NPCs\", \"Right\")\n        \n        -- NPC list helper (models parented to a Folder under workspace.NPC.Function)\n        local function getNpcList()\n            local npcs = {}\n            local funcFolder = workspace:FindFirstChild(\"NPC\") and workspace.NPC:FindFirstChild(\"Function\")\n            if not funcFolder then return npcs end\n            \n            for _, child in ipairs(funcFolder:GetDescendants()) do\n                if typeof(child) == \"Instance\" and child:IsA(\"Model\") and child.Parent and typeof(child.Parent) == \"Instance\" and child.Parent:IsA(\"Folder\") then\n                    table.insert(npcs, child.Name)\n                end\n            end\n            return npcs\n        end\n        \n        local npcList = getNpcList()\n        if #npcList == 0 then\n            table.insert(npcList, \"No NPCs found\")\n        end\n        \n        local selectedNpc = npcList[1]\n        \n        -- Create the dropdown\n        local npcDropdown = NpcSection:CreateDropdown({\n            Name = \"Misc NPCs\",\n            Options = npcList,\n            Default = selectedNpc,\n            Callback = function(value)\n                selectedNpc = value\n            end\n        })\n        \n        -- Teleport to selected NPC button\n        NpcSection:CreateButton({\n            Name = \"Teleport to selected NPC\",\n            Callback = function()\n                if not selectedNpc or selectedNpc == \"No NPCs found\" then\n                    NexusLib:Notify({ Title = \"NPC Teleport\", Message = \"No NPC selected!\", Duration = 2 })\n                    return\n                end\n                \n                local funcFolder = workspace:FindFirstChild(\"NPC\") and workspace.NPC:FindFirstChild(\"Function\")\n                if not funcFolder then\n                    NexusLib:Notify({ Title = \"NPC Teleport\", Message = \"NPC.Function folder not found!\", Duration = 2 })\n                    return\n                end\n                \n                local targetModel = nil\n                for _, child in ipairs(funcFolder:GetDescendants()) do\n                    if typeof(child) == \"Instance\" and child:IsA(\"Model\") and child.Name == selectedNpc and child.Parent and typeof(child.Parent) == \"Instance\" and child.Parent:IsA(\"Folder\") then\n                        targetModel = child\n                        break\n                    end\n                end\n                \n                if not targetModel then\n                    NexusLib:Notify({ Title = \"NPC Teleport\", Message = \"NPC not found!\", Duration = 2 })\n                    return\n                end\n                \n                local hrp = targetModel:FindFirstChild(\"HumanoidRootPart\") or targetModel.PrimaryPart\n                if not hrp then\n                    hrp = targetModel:FindFirstChildWhichIsA(\"BasePart\")\n                end\n                if not hrp then\n                    NexusLib:Notify({ Title = \"NPC Teleport\", Message = \"Cannot find part to teleport to!\", Duration = 2 })\n                    return\n                end\n                \n                local myChar = LocalPlayer.Character\n                if not myChar then return end\n                local myHrp = myChar:FindFirstChild(\"HumanoidRootPart\")\n                if not myHrp then return end\n                \n                myHrp.CFrame = hrp.CFrame + Vector3.new(0, 3, 0)\n                \n                NexusLib:Notify({ Title = \"NPC Teleport\", Message = \"Teleported to \" .. selectedNpc, Duration = 2 })\n            end\n        })\n        -- ===== LEARN SKILL NPC =====\n        local selectedLearnNpc = \"Sage Yijiu\"\n        \n        -- Dropdown with a single option\n        local learnDropdown = Cfg.register(NpcSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Learn Skill NPC\", {\n            Name = \"Learn Skill NPC\",\n            Options = {\"Sage Yijiu\"},\n            Default = \"Sage Yijiu\",\n            Callback = function(value)\n                selectedLearnNpc = value\n            end\n        })), \"Dropdown\", \"Learn Skill NPC\", {\n            Name = \"Learn Skill NPC\",\n            Options = {\"Sage Yijiu\"},\n            Default = \"Sage Yijiu\",\n            Callback = function(value)\n                selectedLearnNpc = value\n            end\n        })\n        \n        -- Teleport to selected NPC button\n        NpcSection:CreateButton({\n            Name = \"Teleport to selected NPC\",\n            Callback = function()\n                local targetModel = workspace:FindFirstChild(\"NPC\") \n                    and workspace.NPC:FindFirstChild(\"LearnSkill\") \n                    and workspace.NPC.LearnSkill:FindFirstChild(\"Sage Yijiu\")\n                \n                if not targetModel then\n                    NexusLib:Notify({ Title = \"Learn Skill\", Message = \"Sage Yijiu not found!\", Duration = 2 })\n                 te.fakeIdMode = 2\n                else\n                    NexusState.fakeIdMode = 1\n                end\n            end\n        })\nCfg.register(StreamerSection:CreateTextbox(Cfg.wrap(\"Textbox\", \"Real Guild Name (Optional)\", {\n            Name = \"Real Guild Name (Optional)\",\n            Placeholder = \"Ten guild that dang hien\",\n            Default = NexusState.realGuildName or \"\",\n            Callback = function(value)\n                if value then\n                    NexusState.realGuildName = tostring(value):gsub(\"^%s+\", \"\"):gsub(\"%s+$\", \"\")\n                    if #(NexusState.realGuildName or \"\") > 0 then\n                        NexusState.enableFakeName()\n                    end\n                end\n            end\n        })), \"Textbox\", \"Real Guild Name (Optional)\", {\n            Name = \"Real Guild Name (Optional)\",\n            Placeholder = \"Ten guild that dang hien\",\n            Default = NexusState.realGuildName or \"\",\n            Callback = function(value)\n                if value then\n                    NexusState.realGuildName = tostring(value):gsub(\"^%s+\", \"\"):gsub(\"%s+$\", \"\")\n                    if #(NexusState.realGuildName or \"\") > 0 then\n                        NexusState.enableFakeName()\n                    end\n                end\n            end\n        })\n\n\n        local LangSection = SettingsTab:CreateSection(\"Language & Localization\")\n        local langOptions = {\"Auto (Roblox Locale)\", \"English\", \"Espanol\", \"Portugues\", \"Thai\", \"Bahasa Indonesia\", \"\", \"\", \"Franais\", \"Deutsch\", \"Italiano\", \"\", \"\", \"Nederlands\", \"Polski\", \"Trke\", \"Filipino\"}\n        local langMap = {\n            [\"Auto (Roblox Locale)\"] = \"auto\",\n            [\"English\"] = \"en\",\n            [\"Espanol\"] = \"es\",\n            [\"Portugues\"] = \"pt\",\n            [\"Thai\"] = \"th\",\n            [\"Bahasa Indonesia\"] = \"id\",\n            [\"\"] = \"zh\",\n            [\"\"] = \"ru\",\n            [\"Franais\"] = \"fr\",\n            [\"Deutsch\"] = \"de\",\n            [\"Italiano\"] = \"it\",\n            [\"\"] = \"ja\",\n            [\"\"] = \"ko\",\n            [\"Nederlands\"] = \"nl\",\n            [\"Polski\"] = \"pl\",\n            [\"Trke\"] = \"tr\",\n            [\"Filipino\"] = \"fil\"\n        }\n        Cfg.register(LangSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"UI Language\", {\n            Name = \"UI Language\",\n            Options = langOptions,\n            Default = \"Auto (Roblox Locale)\",\n            Callback = function(value)\n                NexusState.currentLanguage = langMap[value] or \"auto\"\n                pcall(function()\n                    if I18n and I18n.applyLanguage then\n                        I18n.applyLanguage()\n                    end\n                end)\n                NexusLib:Notify({\n                    Title = I18n.get(\"Language\"),\n                    Message = tostring(I18n.get(\"Language set to: \")) .. tostring(value),\n                    Duration = 2\n                })\n            end\n        })), \"Dropdown\", \"UI Language\", {\n            Name = \"UI Language\",\n            Options = langOptions,\n            Default = \"Auto (Roblox Locale)\",\n            Callback = function(value)\n                NexusState.currentLanguage = langMap[value] or \"auto\"\n                pcall(function()\n                    if I18n and I18n.applyLanguage then\n                        I18n.applyLanguage()\n                    end\n                end)\n                NexusLib:Notify({\n                    Title = I18n.get(\"Language\"),\n                    Message = tostring(I18n.get(\"Language set to: \")) .. tostring(value),\n                    Duration = 2\n                })\n            end\n        })\n\n        local ShieldSection = SettingsTab:CreateSection(\"Nexus Shield\")\n        -- AN TOAN: Nexus Shield bat vinh vien, user KHONG TAT DUOC.\n        -- Khi bat an toan -> callback ignore (khong cho gia tri false), luon ON.\n        NexusState.antiReportEnabled = true\n        Cfg.register(ShieldSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Anti-Report Nexus Users\", {\n            Name = \"Anti-Report Nexus Users\",\n            Default = true,\n            Callback = function(value)\n                -- Bao ve: bat an toan -> neu user thu tat thi bao + luon bat lai\n                NexusState.antiReportEnabled = true\n                NexusLib:Notify({\n                    Title = \"Nexus Shield\",\n                    Message = \"An toan: Nexus Shield luon bat, khong the tat!\",\n                    Duration = 3\n                })\n            end\n        })), \"Toggle\", \"Anti-Report Nexus Users\", {\n            Name = \"Anti-Report Nexus Users\",\n            Default = true,\n            Callback = function(value)\n                -- Bao ve: bat an toan -> neu user thu tat thi bao + luon bat lai\n                NexusState.antiReportEnabled = true\n                NexusLib:Notify({\n                    Title = \"Nexus Shield\",\n                    Message = \"An toan: Nexus Shield luon bat, khong the tat!\",\n                    Duration = 3\n                })\n            end\n        })\n    end\n\n    -- ===== ESP SECTION =====\n    do\n        local EspSection = SettingsTab:CreateSection(\"ESP\")\n        \n        -- ===== ESP PLAYERS =====\n        local espEnabled = false\n        local espThread = nil\n        local espConnections = {}\n        local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n        \n        local function getPlayerStats(player)\n            local stats = {\n                Level = \"N/A\",\n                Cash = \"N/A\",\n                Rod = \"N/A\",\n                Crystal = \"N/A\",\n                EssenceOrb = \"N/A\",\n                Bait = \"N/A\",\n                FishCaught = \"N/A\",\n                Ticket = \"N/A\",\n                TraitReroll = \"N/A\"\n            }\n            local dataFolder = ReplicatedStorage:FindFirstChild(\"Data\")\n            if not dataFolder then return stats end\n            local playerData = dataFolder:FindFirstChild(tostring(player.UserId))\n            if not playerData then return stats end\n            \n            local levelFolder = playerData:FindFirstChild(\"Level\")\n            if levelFolder then\n                local levelVal = levelFolder:FindFirstChild(\"Level\")\n                if levelVal then stats.Level = tostring(levelVal.Value) end\n            end\n            local cashVal = playerData:FindFirstChild(\"Cash\")\n            if cashVal then stats.Cash = tostring(cashVal.Value) end\n            local rodVal = playerData:FindFirstChild(\"FishingRod\")\n            if rodVal then stats.Rod = tostring(rodVal.Value) end\n            local crystalVal = playerData:FindFirstChild(\"Crystal\")\n            if crystalVal then stats.Crystal = tostring(crystalVal.Value) end\n            local essenceVal = playerData:FindFirstChild(\"EssenceOrb\")\n            if essenceVal then stats.EssenceOrb = tostring(essenceVal.Value) end\n            local baitVal = playerData:FindFirstChild(\"EquippedBait\")\n            if baitVal then stats.Bait = tostring(baitVal.Value) end\n            local fishCaughtVal = playerData:FindFirstChild(\"FishCaught\")\n            if fishCaughtVal then stats.FishCaught = tostring(fishCaughtVal.Value) end\n            local ticketVal = playerData:FindFirstChild(\"Ticket\")\n            if ticketVal then stats.Ticket = tostring(ticketVal.Value) end\n            local traitRerollVal = playerData:FindFirstChild(\"Trait Reroll\")\n            if traitRerollVal then stats.TraitReroll = tostring(traitRerollVal.Value) end\n            return stats\n        end\n        \n        local function createEspForPlayer(player)\n            if player == LocalPlayer then return end\n            local character = player.Character\n            if not character then return end\n            local head = character:FindFirstChild(\"Head\")\n            if not head then return end\n            if head:FindFirstChild(\"EspBillboard\") then return end\n            \n            local stats = getPlayerStats(player)\n            local billboard = Instance.new(\"BillboardGui\")\n            billboard.Name = \"EspBillboard\"\n            billboard.Size = UDim2.new(0, 300, 0, 110)\n            billboard.StudsOffset = Vector3.new(0, 3, 0)\n            billboard.AlwaysOnTop = true\n            billboard.Parent = head\n            \n            local frame = Instance.new(\"Frame\")\n            frame.Size = UDim2.new(1, 0, 1, 0)\n            frame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)\n            frame.BackgroundTransparency = 0.6\n            frame.BorderSizePixel = 0\n            frame.Parent = billboard\n            \n            local corner = Instance.new(\"UICorner\")\n            corner.CornerRadius = UDim.new(0, 4)\n            corner.Parent = frame\n            \n            local nameLabel = Instance.new(\"TextLabel\")\n            nameLabel.Size = UDim2.new(1, 0, 0, 18)\n            nameLabel.Position = UDim2.new(0, 0, 0, 0)\n            nameLabel.BackgroundTransparency = 1\n            nameLabel.Font = Enum.Font.GothamBold\n            nameLabel.TextSize = 16\n            nameLabel.TextColor3 = Color3.fromRGB(255, 255, 255)\n            nameLabel.Text = player.Name\n            nameLabel.TextXAlignment = Enum.TextXAlignment.Center\n            nameLabel.Parent = frame\n            \n            local lines = {\n                string.format(\"Lv:%s | Cash:%s\", stats.Level, stats.Cash),\n                string.format(\"Rod:%s\", stats.Rod),\n                string.format(\"Bait:%s\", stats.Bait),\n                string.format(\"Cry:%s | Ess:%s | Tick:%s | Reroll:%s\", stats.Crystal, stats.EssenceOrb, stats.Ticket, stats.TraitReroll),\n                string.format(\"Fish:%s\", stats.FishCaught)\n            }\n            \n            local yOffset = 18\n            for _, line in ipairs(lines) do\n                local label = Instance.new(\"TextLabel\")\n                label.Size = UDim2.new(1, 0, 0, 16)\n                label.Position = UDim2.new(0, 0, 0, yOffset)\n                label.BackgroundTransparency = 1\n                label.Font = Enum.Font.Gotham\n                label.TextSize = 12\n                label.TextColor3 = Color3.fromRGB(200, 200, 200)\n                label.Text = line\n                label.TextXAlignment = Enum.TextXAlignment.Center\n                label.Parent = frame\n                yOffset = yOffset + 16\n            end\n            \n            table.insert(espConnections, { player = player, billboard = billboard })\n        end\n        \n        local function removeEspForPlayer(player)\n            local character = player.Character\n            if not character then return end\n            local head = character:FindFirstChild(\"Head\")\n            if not head then return end\n            local billboard = head:FindFirstChild(\"EspBillboard\")\n            if billboard then billboard:Destroy() end\n            for i, conn in ipairs(espConnections) do\n                if conn.player == player then\n                    table.remove(espConnections, i)\n                    break\n                end\n            end\n        end\n        \n        local function clearAllEsp()\n            for _, conn in ipairs(espConnections) do\n                pcall(function()\n                    if conn.billboard and conn.billboard.Parent then\n                        conn.billboard:Destroy()\n                    end\n                end)\n            end\n            espConnections = {}\n        end\n        \n        local function updateAllEsp()\n            if not espEnabled then return end\n            clearAllEsp()\n            for _, player in ipairs(Players:GetPlayers()) do\n                if player ~= LocalPlayer then\n                    pcall(function() createEspForPlayer(player) end)\n                end\n            end\n        end\n        \n        local function startEsp()\n            if espEnabled then return end\n            espEnabled = true\n            updateAllEsp()\n            \n            local playerAddedConn = Players.PlayerAdded:Connect(function(player)\n                if espEnabled then\n                    task.wait(0.5)\n                    pcall(function() createEspForPlayer(player) end)\n                end\n            end)\n            ance:GetAttribute(\"SecretBoss\") == true\n    end\n\n    local fishingGui = MainGui:FindFirstChild(\"Fishing\")\n    local progression = fishingGui and fishingGui:FindFirstChild(\"ProgressionBar\")\n    local fishNameLabel = progression and progression:FindFirstChild(\"FishName\")\n\n    if (not info.Name or info.Name == \"\" or info.Name == \"???\") and fishNameLabel and fishNameLabel.Text ~= \"\" then\n        info.Name = fishNameLabel.Text\n    end\n\n    return info\nend\n\nlocal function textHasKeyword(text, keywords)\n    text = string.lower(tostring(text or \"\"))\n    for _, keyword in ipairs(keywords) do\n        if string.find(text, keyword, 1, true) then return true end\n    end\n    return false\nend\n\n-- Check whether the target is a Secret Boss\nlocal function isSecretBossTarget(target)\n    local current = target or getCurrentHookTarget()\n    local name = string.lower(tostring(current.Name or \"\"))\n    return current.SecretBoss or NexusState.SecretBossNameSet[name] or textHasKeyword(name, NexusState.SecretBossKeywords)\nend\n\n-- Check whether the target is a Boss\nlocal function isBossTarget(target)\n    local current = target or getCurrentHookTarget()\n    local name = string.lower(tostring(current.Name or \"\"))\n    if isSecretBossTarget(current) then return true end\n    return current.Boss or NexusState.BossNameSet[name] or textHasKeyword(name, NexusState.BossKeywords)\nend\n\n-- Decide whether this target should be farmed\nlocal function shouldFarmBossTarget(target)\n    local current = target or getCurrentHookTarget()\n    if isSecretBossTarget(current) then return true, \"Secret Boss\" end\n    if NexusState.Fishing.Flags.AutoFarmSecretBoss and not NexusState.Fishing.Flags.AutoFarmBoss then return false, \"Normal\" end\n    if NexusState.Fishing.Flags.AutoFarmBoss and isBossTarget(current) then return true, \"Boss\" end\n    return false, \"Normal\"\nend\n\n-- Cancel the cast or release a common fish\nlocal function cancelOrReleaseNormalFish()\n    if not bossFarmEnabled() then return false end\n    local character = LocalPlayer.Character\n    if not character then return false end\n    if not character:GetAttribute(\"Fishing\") then resetBossFarmTarget(); return true end\n\n    NexusState.Fishing.BossFarm.PendingCancel = true\n\n    pcall(function()\n        local fishingGui = MainGui:FindFirstChild(\"Fishing\")\n        local barFrame = fishingGui and fishingGui:FindFirstChild(\"BarFrame\")\n        local bar = barFrame and barFrame:FindFirstChild(\"Bar\")\n        if bar then bar.Position = UDim2.new(-0.15, 0, bar.Position.Y.Scale, bar.Position.Y.Offset) end\n    end)\n\n    if NexusState.Fishing.BossFarm.CurrentToken and tick() - NexusState.Fishing.BossFarm.LastFastCancel > 0.5 then\n        NexusState.Fishing.BossFarm.LastFastCancel = tick()\n        pcall(function() Events.FishingMinigame:FireServer(false, NexusState.Fishing.BossFarm.CurrentToken) end)\n    end\n\n    if not character:GetAttribute(\"Retractable\") then return false end\n    if tick() - NexusState.Fishing.BossFarm.LastCancel < 0.35 then return false end\n\n    NexusState.Fishing.BossFarm.LastCancel = tick()\n    pcall(function()\n        local root = character:FindFirstChild(\"HumanoidRootPart\")\n        if root then Events.Fishing:FireServer(root.CFrame) end\n    end)\n\n    return false\nend\n\n-- textHasKeyword helper (if not defined yet)\nif not textHasKeyword then\n    local function textHasKeyword(text, keywords)\n        text = string.lower(tostring(text or \"\"))\n        for _, keyword in ipairs(keywords) do\n            if string.find(text, keyword, 1, true) then return true end\n        end\n        return false\n    end\nend\n\nlocal function loadBossNameSets()\n    for k in pairs(NexusState.BossNameSet) do NexusState.BossNameSet[k] = nil end\n    for k in pairs(NexusState.SecretBossNameSet) do NexusState.SecretBossNameSet[k] = nil end\n    local infoFolder = ReplicatedStorage:FindFirstChild(\"Info\")\n    if not infoFolder then return end\n\n    pcall(function()\n        local areaRarity = infoFolder:FindFirstChild(\"FishingAreaRarity\")\n        if areaRarity then\n            local rarityData = require(areaRarity)\n            if type(rarityData) == \"table\" and type(rarityData[\"Secret Boss\"]) == \"table\" then\n                for fishName in pairs(rarityData[\"Secret Boss\"]) do\n                    local name = string.lower(tostring(fishName))\n                    NexusState.SecretBossNameSet[name] = true\n                    NexusState.BossNameSet[name] = true\n                end\n            end\n        end\n    end)\n\n    pcall(function()\n        local inventory = infoFolder:FindFirstChild(\"Inventory\")\n        if inventory then\n            for _, module in pairs(inventory:GetChildren()) do\n                if typeof(module) == \"Instance\" and typeof(module) == \"Instance\" and module:IsA(\"ModuleScript\") then\n                    local ok, itemData = pcall(require, module)\n                    if ok and type(itemData) == \"table\" then\n                        local name = string.lower(tostring(itemData.FishName or module.Name))\n                        if itemData.Boss == true or itemData.SpecialBoss == true or itemData.SecretBoss == true then\n                            NexusState.BossNameSet[name] = true\n                        end\n                        if itemData.SecretBoss == true then\n                            NexusState.SecretBossNameSet[name] = true\n                        end\n                    end\n                end\n            end\n        end\n    end)\nend\n-- Defer heavy boss-name scan until after boot so opening the hub stays smooth\ntask.spawn(function()\n    task.wait(3)\n    if not alive() then return end\n    pcall(loadBossNameSets)\nend)\n\n-- ===== BUILD MAIN UI =====\nruntimeEnv.NexusStage(\"dung UI\")\nlocal Window\ndo\n    local ok, result = pcall(function()\n        return NexusLib:CreateWindow({\n            Title = \"NEXUS\",\n            Subtitle = \"HEAVYWEIGHT FISHING - LIVE SESSION\",\n            Keybind = Enum.KeyCode.RightAlt,\n        })\n    end)\n    if not ok or type(result) ~= \"table\" then\n        runtimeEnv.NexusStage(\"UI window failed\")\n        runtimeEnv.NexusReport(\"Nexus UI failed\", \"CreateWindow: \" .. tostring(result))\n        return\n    end\n    Window = result\nend\n\nlocal Fishing = NexusState.Fishing\nlocal MiscFlags = NexusState.MiscFlags\n\n-- ============================================================\n-- ===== SHARED HELPERS (DECLARED UP FRONT) =====\n-- ============================================================\n\nlocal function GetPlayerData()\n    if not Data then return nil end\n    return Data:FindFirstChild(tostring(LocalPlayer.UserId))\nend\n\nlocal function GetModule(folder, name)\n    local m = folder:FindFirstChild(name)\n    if m then\n        local ok, mod = pcall(require, m)\n        if ok and type(mod) == \"table\" then return mod end\n    end\n    return nil\nend\n\nlocal function GetAvailableBaits()\n    local p = GetPlayerData()\n    if not p then return {} end\n    local baits = {}\n    local baitFolder = p:FindFirstChild(\"Bait\")\n    if not baitFolder then return {} end\n    for _, b in pairs(baitFolder:GetChildren()) do\n        if typeof(b) == \"Instance\" and typeof(b) == \"Instance\" and b:IsA(\"NumberValue\") and b.Value > 0 then\n            table.insert(baits, b.Name)\n        end\n    end\n    return baits\nend\n\nlocal function GetBaitStats(baitName)\n    local mod = GetModule(Info.Bait, baitName)\n    if mod then return {Luck = mod.Luck or 0} end\n    return {Luck = 0}\nend\n\nlocal function GetBestBait()\n    local baits = GetAvailableBaits()\n    local best, bestLuck = nil, -1\n    for _, name in ipairs(baits) do\n        local s = GetBaitStats(name)\n        if s.Luck > bestLuck then bestLuck = s.Luck; best = name end\n    end\n    return best\nend\n\nlocal function EquipBait(baitName)\n    if not baitName then return false end\n    return pcall(function() Events.EquipBait:InvokeServer(baitName) end)\nend\n\nlocal function GetOwnedRods()\n    local p = GetPlayerData()\n    if not p then return {} end\n    local rods = {}\n    for _, f in pairs(p.FishingRodInventory:GetChildren()) do\n        if typeof(f) == \"Instance\" and typeof(f) == \"Instance\" and f:IsA(\"Folder\") and f.Owned and f.Owned.Value == true then\n            table.insert(rods, f.Name)\n        end\n    end\n    return rods\nend\n\nlocal function GetRodStats(rodName)\n    local mod = GetModule(Info.Inventory, rodName)\n    if mod then return {Power = mod.Power or 0, Luck = mod.Luck or 0} end\n    return {Power = 0, Luck = 0}\nend\n\nlocal function GetBestRod()\n    local rods = GetOwnedRods()\n    local best, bestScore = nil, -1\n    for _, name in ipairs(rods) do\n        local s = GetRodStats(name)\n        local score = s.Power + s.Luck\n        if score > bestScore then bestScore = score; best = name end\n    end\n    return best\nend\n\nlocal function EquipRod(rodName)\n    if not rodName then return false end\n    return pcall(function() Events.EquipFishingRod:InvokeServer(rodName) end)\nend\n\nlocal function GetAvailableOrbs()\n    local p = GetPlayerData()\n    if not p then return {} end\n    local orbs = {}\n    local orbFolder = p:FindFirstChild(\"Orb\")\n    if not orbFolder then return {} end\n    for _, f in pairs(orbFolder:GetChildren()) do\n        if typeof(f) == \"Instance\" and typeof(f) == \"Instance\" and f:IsA(\"Folder\") then\n            local eq = f:FindFirstChild(\"Equipping\")\n            if eq and eq.Value == false then\n                table.insert(orbs, f.Name)\n            end\n        end\n    end\n    return orbs\nend\n\nlocal function GetOrbStats(orbName)\n    local p = GetPlayerData()\n    if not p then return {} end\n    local f = p.Orb:FindFirstChild(orbName)\n    if not f then return {} end\n    local stats = {}\n    for _, child in pairs(f:GetChildren()) do\n        if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"NumberValue\") and child.Name ~= \"Equipping\" and child.Name ~= \"Favorite\" then\n            stats[child.Name] = child.Value\n        end\n    end\n    return stats\nend\n\nlocal function GetBestOrb()\n    local orbs = GetAvailableOrbs()\n    local best, bestScore = nil, -1\n    for _, name in ipairs(orbs) do\n        local s = GetOrbStats(name)\n        local score = (s.Damage or 0) * 2 + (s.Luck or 0) * 1.5 + (s.Cash or 0) * 0.5\n        if score > bestScore then bestScore = score; best = name end\n    end\n    return best\nend\n\nlocal function EquipOrb(orbName)\n    if not orbName then return false end\n    return pcall(function() Events.EquipOrb:InvokeServer(orbName) end)\nend\n\n-- Parse one Data inventory child into (fishName, weightKg, count).\n-- Real server format: Name = \"FishName | 3500000 KG\" (may add \" | Favorite\"),\n-- Value = stack count (IntValue). Older format kept as fallback.\nlocal function parseCraftWeight(str)\n    if not str or str == \"\" then return nil end\n    local s = tostring(str):gsub(\"^%s+\", \"\"):gsub(\"%s+$\", \"\")\n    s = s:gsub(\"%s*[Kk][Gg]%s*$\", \"\")\n    s = s:gsub(\"^%s+\", \"\"):gsub(\"%s+$\", \"\")\n    local direct = tonumber(s)\n    if direct then return direct end\n    local num, suffix = s:match(\"^([%d%.]+)%s*([KkMmBbTt])%+?$\")\n    num = tonumber(num)\n    if not num then return nil end\n    local mult = { K = 1000, M = 1000000, B = 1000000000, T = 1000000000000 }\n    local m = mult[string.upper(suffix or \"\")]\n    if not m then return nil end\n    return num * m\nend\n\nlocal function parseCraftFishEntry(item)\n    if not item then return nil, nil, 0 end\n    local rawName = tostring(item.Name or \"\")\n    rawName = string.split(rawName, \"| Favorite\")[1]\n    local count = 1\n    pcall(function()\n        if type(item.Value) == \"number\" then count = item.Value end\n    end)\n    local parts = {}\n    for part in string.gmatch(rawName, \"[^|]+\") do table.insert(parts, part) end\n    local function trim(s) return tostring(s or \"\"):gsub(\"^%s+\", \"\"):gsub(\"%s+$\", \"\") end\n    local fishName = trim(parts[1])\n    local weight = nil\n    if #parts >= 2 then\n        weight = parseCraftWeight(string.split(trim(parts[2]), \" \")[1])\n    end\n    if not weight then\n        pcall(function()\n            local w = item:GetAttribute(\"Weight\")\n            if type(w) == \"number\" and w > BackgroundTransparencyScript error: ScreenGuiPositionspawncodeAN4\x02%s+$Key\x1E\x0F\\\x03\xE0\x04",
