     pcall(function()\n            local npc = Workspace:FindFirstChild(\"NPC\")\n            local bosses = npc and npc:FindFirstChild(\"Boss\")\n            local enzo = bosses and bosses:FindFirstChild(\"Enzo\")\n            inFight = enzo ~= nil and enzo:GetAttribute(\"InFight\") == true\n        end)\n        if inFight then return true end\n        local fishing = MainGui:FindFirstChild(\"Fishing\")\n        local bossBar = fishing and fishing:FindFirstChild(\"BossFightBar\")\n        return bossBar ~= nil and bossBar.Visible == true\n    end\n\n    local function setAutoEnzo(value)\n        NexusState.AutoEnzoEnabled = value == true\n        Fishing.Flags.AutoSkillCheck = NexusState.AutoEnzoEnabled\n            or NexusState.AutoLongDiaohaiEnabled == true\n            or NexusState.AutoBlackTortoiseEnabled == true\n    end\n\n    local function setAutoFightEnzo(value)\n        Fishing.Flags.AutoFightEnzo = value\n        if Fishing.FightEnzoThread then task.cancel(Fishing.FightEnzoThread); Fishing.FightEnzoThread = nil end\n        if runtimeEnv.NexusFightEnzoThread then task.cancel(runtimeEnv.NexusFightEnzoThread); runtimeEnv.NexusFightEnzoThread = nil end\n        if value and StartBossFight then\n            Fishing.FightEnzoThread = task.spawn(function()\n                while Fishing.Flags.AutoFightEnzo do\n                    pcall(function() StartBossFight:FireServer(\"Enzo\", Fishing.Flags.BossFightMode or \"Normal\") end)\n                    task.wait(0.3)\n                end\n                Fishing.FightEnzoThread = nil\n                runtimeEnv.NexusFightEnzoThread = nil\n            end)\n            runtimeEnv.NexusFightEnzoThread = Fishing.FightEnzoThread\n        end\n    end\n\n    local function setAutoFightLongDiaohai(value)\n        Fishing.Flags.AutoFightLongDiaohai = value\n        if Fishing.FightLongDiaohaiThread then task.cancel(Fishing.FightLongDiaohaiThread); Fishing.FightLongDiaohaiThread = nil end\n        if value and StartBossFight then\n            Fishing.FightLongDiaohaiThread = task.spawn(function()\n                while Fishing.Flags.AutoFightLongDiaohai do\n                    pcall(function() StartBossFight:FireServer(\"Long Diaohai\", Fishing.Flags.LongDiaohaiFightMode or \"Normal\") end)\n                    task.wait(0.4)\n                end\n            end)\n        end\n    end\n\n    Cfg.register(FarmSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Fight Long Diaohai\", { Name = \"Auto Fight Long Diaohai\", Default = false, Callback = function(V) setAutoFightLongDiaohai(V) end })), \"Toggle\", \"Auto Fight Long Diaohai\", { Name = \"Auto Fight Long Diaohai\", Default = false, Callback = function(V) setAutoFightLongDiaohai(V) end })\n    Cfg.register(FarmSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Long Diaohai Fight Mode\", { Name = \"Long Diaohai Fight Mode\", Options = {\"Normal\", \"Hard\", \"Nightmare\"}, Default = \"Normal\", Callback = function(V) Fishing.Flags.LongDiaohaiFightMode = V end })), \"Dropdown\", \"Long Diaohai Fight Mode\", { Name = \"Long Diaohai Fight Mode\", Options = {\"Normal\", \"Hard\", \"Nightmare\"}, Default = \"Normal\", Callback = function(V) Fishing.Flags.LongDiaohaiFightMode = V end })\n    Cfg.register(FarmSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Long Diaohai\", { Name = \"Auto Long Diaohai\", Default = false, Callback = function(V) Fishing.Flags.AutoLongDiaohai = V end })), \"Toggle\", \"Auto Long Diaohai\", { Name = \"Auto Long Diaohai\", Default = false, Callback = function(V) Fishing.Flags.AutoLongDiaohai = V end })\n\n    Cfg.register(FarmSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Enzo\", { Name = \"Auto Enzo\", Default = false, Callback = function(V) setAutoEnzo(V) end })), \"Toggle\", \"Auto Enzo\", { Name = \"Auto Enzo\", Default = false, Callback = function(V) setAutoEnzo(V) end })\n        Cfg.register(FarmSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Auto Enzo Fight Mode\", {\n        Name = \"Auto Enzo Fight Mode\",\n        Options = {\"Normal\", \"Hard\", \"Nightmare\"},\n        Default = Fishing.Flags.BossFightMode or \"Normal\",\n        Callback = function(value) Fishing.Flags.BossFightMode = value end\n    })), \"Dropdown\", \"Auto Enzo Fight Mode\", {\n        Name = \"Auto Enzo Fight Mode\",\n        Options = {\"Normal\", \"Hard\", \"Nightmare\"},\n        Default = Fishing.Flags.BossFightMode or \"Normal\",\n        Callback = function(value) Fishing.Flags.BossFight\"] = \"Lempar Otomatis\",\n            [\"Auto Farm Boss\"] = \"Auto Farm Boss\",\n            [\"Auto Farm Secret Boss\"] = \"Auto Farm Secret Boss\",\n            [\"Auto Skill\"] = \"Auto Skill\",\n            [\"Auto Sell Fish\"] = \"Auto Jual Ikan\",\n            [\"Auto Enzo\"] = \"Auto Enzo QTE\",\n            [\"Anti AFK\"] = \"Anti AFK\",\n            [\"Farm On Weather\"] = \"Auto Farm Berdasarkan Cuaca\",\n            [\"Auto Equip Best Bait\"] = \"Pasang Umpan Terbaik\",\n            [\"Auto Equip Fishing Rod (Slot 1)\"] = \"Pegang Pancingan Otomatis\",\n            [\"Auto Nameless\"] = \"Auto Tanpa Nama\",\n            [\"Auto Favourite Fishes\"] = \"Auto Favoritkan Ikan\",\n            [\"Auto Teleport + Interact (Pray) Spirit\"] = \"Auto Doa Roh\",\n            [\"Enable Auto Farm Fish\"] = \"Aktifkan Auto Farm\",\n            [\"Auto Do Daily Quest\"] = \"Auto Misi Harian\",\n            [\"Auto Do Ticket Quest (Fast)\"] = \"Auto Misi Tiket (Cepat)\",\n            [\"Auto Claim Ticket Quest (Fast)\"] = \"Auto Klaim Tiket (Cepat)\",\n            [\"Auto Rebirth\"] = \"Auto Kelahiran Kembali\",\n            [\"Auto craft bait\"] = \"Auto buat umpan\",\n            [\"Auto craft selected rod\"] = \"Auto buat pancingan\",\n            [\"Auto fish for bait materials\"] = \"Auto pancing bahan umpan\",\n            [\"Fly Mode\"] = \"Mode Terbang\",\n            [\"Walk On Water\"] = \"Berjalan di Atas Air\",\n            [\"Infinite Jump\"] = \"Lompat Tak Terbatas\",\n            [\"Noclip\"] = \"Noclip\",\n            [\"Full Bright\"] = \"Kecerahan Penuh\",\n            [\"Fake Name Display\"] = \"Nama Palsu Aktif\",\n            [\"Anti-Report Nexus Users\"] = \"Anti-Laporkan Pengguna Nexus\",\n            [\"Enable Staff Watch\"] = \"Aktifkan Deteksi Staff\",\n            [\"Enable Notifications\"] = \"Aktifkan Notifikasi\",\n            [\"UI Language\"] = \"Bahasa UI\",\n            [\"Skill Mode\"] = \"Mode Skill\",\n            [\"Skill Sequence Order\"] = \"Urutan Skill\",\n            [\"Skill Delay (seconds)\"] = \"Jeda Skill (detik)\",\n            [\"Select Island\"] = \"Pilih Pulau\",\n            [\"Buy Now\"] = \"Beli Sekarang\",\n            [\"Craft rod now\"] = \"Buat Pancingan Sekarang\",\n            [\"Craft bait now\"] = \"Buat Umpan Sekarang\",\n            [\"Exchange now\"] = \"Tukar Sekarang\"\n        }\n    }\n\n    function I18n.getCurrentLanguage()\n        if NexusState.currentLanguage == \"auto\" then\n            return NexusState.detectedLanguage or \"en\"\n        end\n        return NexusState.currentLanguage or \"en\"\n    end\n\n    function I18n.get(key, fallback)\n        if not key or type(key) ~= \"string\" then return fallback or key end\n        local lang = I18n.getCurrentLanguage()\n        if lang == \"en\" then return fallback or key end\n        local dict = DICTIONARY[lang]\n        if dict and dict[key] then return dict[key] end\n        return fallback or key\n    end\n\n    local function translateObject(obj)\n        if not obj or typeof(obj) ~= \"Instance\" then return end\n        local lang = I18n.getCurrentLanguage()\n        if lang == \"en\" then return end\n        pcall(function()\n            if (obj:IsA(\"TextLabel\") or obj:IsA(\"TextButton\") or obj:IsA(\"TextBox\")) then\n                local currentText = obj.Text\n                if not currentText or #currentText == 0 then return end\n                \n                local dict = DICTIONARY[lang]\n                \n                local orig = obj:GetAttribute(\"NexusOrigText\")\n                if not orig or (dict and dict[currentText]) then\n                    orig = currentText\n                    obj:SetAttribute(\"NexusOrigText\", orig)\n                end\n                \n                if orig and #orig > 0 then\n                    if lang == \"en\" then\n                        if obj.Text ~= orig then\n                            obj.Text = orig\n                        end\n                    else\n                        local trans = dict and dict[orig]\n                        if trans and obj.Text ~= trans then\n                            obj.Text = trans\n                        end\n                    end\n                end\n            end\n        end)\n    end\n\n    local function applyLanguageToGui(gui)\n        if not gui then return end\n        pcall(function()\n            for _, desc in ipairs(gui:GetDescendants()) do\n                translateObject(desc)\n            end\n        end)\n    end\n\n    function I18n.applyLanguage()\n        local pg = LocalPlayer:FindFirstChild(\"PlayerGui\")\n        if pg then\n            applyLanguageToGui(pg:FindFirstChild(\"NexusPanel\"))\n            applyLanguageToGui(pg:FindFirstChild(\"NexusNotifications\"))\n        end\n        pcall(function()\n            local cg = game:GetService(\"CoreGui\")\n            if cg then\n                applyLanguageToGui(cg:FindFirstChild(\"NexusPanel\"))\n                applyLanguageToGui(cg:FindFirstChild(\"NexusNotifications\"))\n            end\n        end)\n    end\n\n    function I18n.initListeners()\n        local function hookGui(gui)\n            if not gui then return end\n            gui.DescendantAdded:Connect(function(desc)\n                task.wait(0.03)\n                translateObject(desc)\n            end)\n        end\n\n        local pg = LocalPlayer:FindFirstChild(\"PlayerGui\")\n        if pg then\n            local panel = pg:FindFirstChild(\"NexusPanel\")\n            if panel then hookGui(panel) end\n            local notifs = pg:FindFirstChild(\"NexusNotifications\")\n            if notifs then hookGui(notifs) end\n\n            pg.ChildAdded:Connect(function(child)\n                if child.Name == \"NexusPanel\" or child.Name == \"NexusNotifications\" then\n                    hookGui(child)\n                    task.wait(0.1)\n                    applyLanguageToGui(child)\n                end\n            end)\n        end\n\n        pcall(function()\n            local cg = game:GetService(\"CoreGui\")\n            if cg then\n                local panel = cg:FindFirstChild(\"NexusPanel\")\n                if panel then hookGui(panel) end\n                local notifs = cg:FindFirstChild(\"NexusNotifications\")\n                if notifs then hookGui(notifs) end\n\n                cg.ChildAdded:Connect(function(child)\n                    if child.Name == \"NexusPanel\" or child.Name == \"NexusNotifications\" then\n                        hookGui(child)\n                        task.wait(0.1)\n                        applyLanguageToGui(child)\n                    end\n                end)\n            end\n        end)\n    end\nend\n\n-- ===== FAKE NAME (STREAMER MODE) CORE =====\n-- ============================================================\ndo\n    local realName = LocalPlayer.Name\n    local realDisplayName = LocalPlayer.DisplayName\n    local fakeNameConn = nil\n    local fakeNameThread = nil\n    local maskIdsInText -- forward declare (dinh nghia ben duoi)\n\n    local function replacePlain(text, find, repl)\n        if find == \"\" then return text end\n        local parts = {}\n        local start = 1\n        while true do\n            local s, e = string.find(text, find, start, true)\n            if not s then\n                table.insert(parts, string.sub(text, start))\n                break\n            end\n            table.insert(parts, string.sub(text, start, s - 1))\n            table.insert(parts, repl)\n            start = e + 1\n        end\n        return table.concat(parts)\n    end\n\n    local function replaceTextInObject(obj)\n        if not NexusState.fakeNameEnabled then return end\n        if not obj or typeof(obj) ~= \"Instance\" then return end\n        pcall(function()\n            if typeof(obj) == \"Instance\" and typeof(obj) == \"Instance\" and obj:IsA(\"TextLabel\") or obj:IsA(\"TextButton\") or obj:IsA(\"TextBox\") then\n                local text = obj.Text\n                if text and #text > 0 then\n                    local updated = false\n                    if realDisplayName ~= \"\" and string.find(text, realDisplayName, 1, true) then\n                        text = replacePlain(text, realDisplayName, NexusState.fakeDisplayName or \"NexusPlayer\")\n                        updated = true\n                    end\n                    if realName ~= \"\" and string.find(text, realName, 1, true) then\n                        text = replacePlain(text, realName, NexusState.fakeName or \"NexusPlayer\")\n                        updated = true\n                    end\n                    -- Guild display: doi ten guild that -> fake guild de khong bi ban\n                    if NexusState.realGuildName and #NexusState.realGuildName > 0 then\n                        local rg = tostring(NexusState.realGuildName)\n                        if rg ~= \"ZION\" and not string.find(text, \"ZION\", 1, true) and string.find(text, rg, 1, true) then\n                            text = replacePlain(text, rg, NexusState.fakeGuildName or \"NexusGuild\")\n                            updated = true\n                        end\n                    end\n                    -- Che luon ID (UserId / PlaceId / JobId) chu khong chi ten\n                    if maskIdsInText then\n                        local masked, idChanged = maskIdsInText(text)\n                        if idChanged then\n                            text = masked\n                            updated = true\n                        end\n                    end\n                    if updated then\n                        obj.Text = text\n                    end\n                end\n            end\n        end)\n    end\n\n    -- Che ID: doi ten khong thoi van bi report vi nguoi ta doc UserId / PlaceId /\n    -- JobId tren man hinh (hoac trong anh chup). Nen phai che luon cac ID nay.\n    local realUserId = tostring(LocalPlayer.UserId)\n    local realPlaceId = tostring(game.PlaceId)\n\n    function maskIdsInText(text)\n        if not NexusState.fakeNameEnabled then return text, false end\n        local changed = false\n        if #realUserId >= 5 and string.find(text, realUserId, 1, true) then\n            if (NexusState.fakeIdMode or 1) == 2 then\n                text = string.gsub(text, realUserId, \"****\")\n            else\n                text = string.gsub(text, realUserId, tostring(NexusState.fakeUserId or \"0\"))\n            end\n            changed = true\n        end\n        if #realPlaceId >= 5 and string.find(text, realPlaceId, 1, true) then\n            text = string.gsub(text, realPlaceId, \"0000000000\")\n            changed = true\n        end\n        local guidPat = \"%x%x%x%x%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%x%x%x%x%x%x%x%x\"\n        if string.find(text, guidPat) then\n            text = string.gsub(text, guidPat, \"********-****-****-****-************\")\n            changed = true\n        end\n        return text, changed\n    end\n\n    local function applyFakeNameToAll()\n        if not NexusState.fakeNameEnabled then return end\n        local pg = LocalPlayer:FindFirstChild(\"PlayerGui\")\n        if pg then\n            for _, v in ipairs(pg:GetDescendants()) do\n                replaceTextInObject(v)\n            end\n        end\n        local char = LocalPlayer.Character\n        if char then\n            for _, v in ipairs(char:GetDescendants()) do\n                replaceTextInObject(v)\n            end\n        end\n        pcall(function()\n            local cg = game:GetService(\"CoreGui\")\n            if cg then\n                for _, v in ipairs(cg:GetDescendants()) do\n                    replaceTextInObject(v)\n                end\n            end\n        end)\n    end\n\n    function NexusState.enableFakeName()\n        if NexusState.fakeNameEnabled then return end\n        NexusState.fakeNameEnabled = true\n        applyFakeNameToAll()\n\n        local pg = LocalPlayer:FindFirstChild(\"PlayerGui\")\n        if pg then\n            fakeNameConn = pg.DescendantAdded:Connect(function(desc)\n                if NexusState.fakeNameEnabled then\n                    task.wait(0.05)\n                    replaceTextInObject(desc)\n                end\n            end)\n        end\n\n        fakeNameThread = task.spawn(function()\n            while NexusState.fakeNameEnabled do\n                pcall(applyFakeNameToAll)\n                task.wait(1.5)\n            end\n        end)\n        NexusLiraType\n            \n            -- Lock the camera onto the target\n            camera.CameraSubject = targetHrp\n            camera.CameraType = Enum.CameraType.Custom\n            \n            NexusLib:Notify({ Title = \"Spectate\", Message = \"Spectating \" .. targetPlayer.Name, Duration = 2 })\n        end\n        \n        -- Stop spectate\n        local function stopSpectate()\n            spectateEnabled = false\n            spectateTarget = nil\n            \n            -- Reset the camera back to the local player\n            pcall(function()\n                local camera = workspace.CurrentCamera\n                if oldSubject then\n                    camera.CameraSubject = oldSubject\n                    oldSubject = nil\n                end\n                if oldCameraType then\n                    camera.CameraType = oldCameraType\n                    oldCameraType = nil\n                end\n            end)\n            \n            NexusLib:Notify({ Title = \"Spectate\", Message = \"Stopped spectating\", Duration = 2 })\n        end\n        \n        -- Toggle Spectate Player\n        local spectateToggle = Cfg.register(PlayerSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Spectate Player\", {\n            Name = \"Spectate Player\",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    startSpectate()\n                else\n                    stopSpectate()\n                end\n            end\n        })), \"Toggle\", \"Spectate Player\", {\n            Name = \"Spectate Player\",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    startSpectate()\n                else\n                    stopSpectate()\n                end\n            end\n        })\n        \n        -- Persist the toggle in NexusState\n        NexusState.spectateToggle = spectateToggle\n        \n        -- Handle the target leaving or their character resetting\n        local function onTargetCharacterAdded()\n            if spectateEnabled and spectateTarget then\n                local char = spectateTarget.Character\n                if char then\n                    local hrp = char:FindFirstChild(\"HumanoidRootPart\")\n                    if hrp then\n                        workspace.CurrentCamera.CameraSubject = hrp\n                    end\n                end\n            end\n        end\n        \n        -- Listen for the target's character changing\n        local charAddedConn = nil\n        local playerRemovingConn = Players.PlayerRemoving:Connect(function(player)\n            if spectateEnabled and player == spectateTarget then\n                stopSpectate()\n                if NexusState.spectateToggle then\n                    NexusState.spectateToggle:Set(false)\n                end\n            end\n        end)\n        \n        -- While spectating, watch the target's CharacterAdded\n        local function monitorTarget()\n            if spectateEnabled and spectateTarget then\n                if charAddedConn then charAddedConn:Disconnect() end\n                charAddedConn = spectateTarget.CharacterAdded:Connect(function()\n                    task.wait(0.5)\n                    onTargetCharacterAdded()\n                end)\n            else\n                if charAddedConn then\n                    charAddedConn:Disconnect()\n                    charAddedConn = nil\n                end\n            end\n        end\n        \n        -- Wrap startSpectate to attach the monitor\n        local originalStart = startSpectate\n        startSpectate = function()\n            originalStart()\n            monitorTarget()\n        end\n        \n        -- Wrap stopSpectate to clean up\n        local originalStop = stopSpectate\n        stopSpectate = function()\n            originalStop()\n            if charAddedConn then\n                charAddedConn:Disconnect()\n                charAddedConn = nil\n            end\n        end\n        \n        table.insert(espConnections, { conn = playerRemovingConn })\n    end\n    -- ===== NPCs SECTION =====\n    do\n        local NpcSection = TeleportTab:CreateSection(\"NPCs\", \"Right\")\n        \n        -- NPC list helper (models parented to a Folder under workspace.NPC.Function)\n        local function getNpcList()\n            local npcs = {}\n            local funcFolder = workspace:FindFirstChild(\"NPC\") and workspace.NPC:FindFirstChild(\"Function\")\n            if not funcFolder then return npcs end\n            \n            for _, child in ipairs(funcFolder:GetDescendants()) do\n                if typeof(child) == \"Instance\" and child:IsA(\"Model\") and child.Parent and typeof(child.Parent) == \"Instance\" and child.Parent:IsA(\"Folder\") then\n                    table.insert(npcs, child.Name)\n                end\n            end\n            return npcs\n        end\n        \n        local npcList = getNpcList()\n        if #npcList == 0 then\n            table.insert(npcList, \"No NPCs found\")\n        end\n        \n        local selectedNpc = npcList[1]\n        \n        -- Create the dropdown\n        local npcDropdown = NpcSection:CreateDropdown({\n            Name = \"Misc NPCs\",\n            Options = npcList,\n            Default = selectedNpc,\n            Callback = function(value)\n                selectedNpc = value\n            end\n        })\n        \n        -- Teleport to selected NPC button\n        NpcSection:CreateButton({\n            Name = \"Teleport to selected NPC\",\n            Callback = function()\n                if not selectedNpc or selectedNpc == \"No NPCs found\" then\n                    NexusLib:Notify({ Title = \"NPC Teleport\", Message = \"No NPC selected!\", Duration = 2 })\n                    return\n                end\n                \n                local funcFolder = workspace:FindFirstChild(\"NPC\") and workspace.NPC:FindFirstChild(\"Function\")\n                if not funcFolder then\n                    NexusLib:Notify({ Title = \"NPC Teleport\", Message = \"NPC.Function folder not found!\", Duration = 2 })\n                    return\n                end\n                \n                local targetModel = nil\n                for _, child in ipairs(funcFolder:GetDescendants()) do\n                    if typeof(child) == \"Instance\" and child:IsA(\"Model\") and child.Name == selectedNpc and child.Parent and typeof(child.Parent) == \"Instance\" and child.Parent:IsA(\"Folder\") then\n                        targetModel = child\n                        break\n                    end\n                end\n                \n                if not targetModel then\n                    NexusLib:Notify({ Title = \"NPC Teleport\", Message = \"NPC not found!\", Duration = 2 })\n                    return\n                end\n                \n                local hrp = tar